"use client";

import Link from "next/link";
import useSWR from "swr";
import Shell from "@/components/layout/Shell";
import ReadinessReportView, { ClassificationBadge } from "@/components/readiness/ReadinessReportView";
import { ApiError, type ReadinessReportResponse } from "@/lib/api";
import { fetcher } from "@/lib/fetcher";

/**
 * UC-13, FR-08.6: the student's own readiness report, and only their own (SR-08).
 * The report is generated by their teacher (FR-08.2); until then this page says why
 * there is none: fewer than 3 experiments (FR-08.4), or not generated yet.
 */
export default function ReadinessPage() {
  const { data, isLoading, error } = useSWR<ReadinessReportResponse, ApiError>("/readiness", fetcher);

  if (isLoading) return <Shell><div className="flex justify-center py-24 text-4xl animate-spin">⚗️</div></Shell>;

  if (error || !data) {
    // The 422 body carries the counts; ApiError keeps only the message, which states them.
    const notEligible = error?.code === "not_eligible";
    return (
      <Shell>
        <div className="p-6 max-w-lg mx-auto text-center">
          <span className="text-6xl" aria-hidden>🧠</span>
          <h1 className="font-fredoka font-600 text-xl text-ink mt-4 mb-2">AI Readiness Report</h1>
          {notEligible ? (
            <>
              <p className="text-sub font-700 text-sm">{error?.message}</p>
              <p className="text-sub font-700 text-sm mt-1">Finish experiments to unlock your report.</p>
              <Link href="/experiments"
                    className="inline-block mt-5 px-5 py-3 rounded-2xl bg-green hover:bg-green-d text-white font-fredoka font-600 shadow-md">
                Go to experiments 🔬
              </Link>
            </>
          ) : error?.code === "no_report" ? (
            <p className="text-sub font-700 text-sm">
              You have done enough experiments. Your teacher will generate your report soon.
            </p>
          ) : (
            <p className="text-sub font-700 text-sm">Your report could not be loaded. Check your connection and try again.</p>
          )}
        </div>
      </Shell>
    );
  }

  const r = data.report;

  return (
    <Shell>
      <div className="p-4 md:p-6 max-w-lg mx-auto space-y-5">
        <div>
          <h1 className="font-fredoka font-600 text-2xl text-ink">AI Readiness Report 🧠</h1>
          <p className="text-sub font-700 text-sm mt-1">How ready you are for the real chemistry lab.</p>
        </div>
        <div className="text-center">
          <ClassificationBadge value={r.classification} size="lg" />
        </div>
        <ReadinessReportView report={r} />
      </div>
    </Shell>
  );
}
